// [S4] Deterministic Safety / Validation Agent
using FamilyVeda.Domain.Safety;

namespace FamilyVeda.UnitTests;

public sealed class SafetyValidationServiceTests
{
    [Theory]
    [InlineData("Fasting glucose increased from 92 mg/dL to 104 mg/dL.")]
    [InlineData("Total cholesterol: 188 mg/dL.")]
    [InlineData("Glucose: 104MG/DL.")]
    public void Validate_WhenDraftContainsLabConcentration_AllowsEvidence(string draft)
    {
        var result = new SafetyValidationService().Validate(new SafetyInput(false, draft, true, 0.9m, 0.6m));

        Assert.True(result.CanContinue);
        Assert.Empty(result.Violations);
    }

    [Theory]
    [InlineData("Dose: 5 mg.")]
    [InlineData("Dose: 0.5 mcg.")]
    [InlineData("Dose: 1 g.")]
    [InlineData("Dose: 2 mL.")]
    [InlineData("Glucose: 92 mg/dL. Dose: 5 mg.")]
    [InlineData("Value: 5 mg/dLextra.")]
    [InlineData("Value: 5 mg/dL2.")]
    [InlineData("Value: 5 mg/dL_daily.")]
    public void Validate_WhenDraftContainsDoseOrMalformedConcentration_BlocksDosing(string draft)
    {
        var result = new SafetyValidationService().Validate(new SafetyInput(false, draft, true, 0.9m, 0.6m));

        Assert.False(result.CanContinue);
        Assert.Contains("DOSING_CONTENT", result.Violations);
    }

    [Theory]
    [InlineData("Glucose: 92 mg/dL. Take medication.")]
    [InlineData("Glucose: 92 mg/dL. Metformin.")]
    public void Validate_WhenLabEvidenceContainsMedicationContent_StillBlocksContent(string draft)
    {
        var result = new SafetyValidationService().Validate(new SafetyInput(false, draft, true, 0.9m, 0.6m));

        Assert.False(result.CanContinue);
        Assert.Contains("PROHIBITED_CONTENT", result.Violations);
    }

    [Fact]
    public void Validate_WhenEmergencyRedFlagExists_HaltsBeforeLlmAndReturnsReferralOnly()
    {
        var service = new SafetyValidationService();
        var llmWasInvoked = false;
        var input = new SafetyInput(
            HasEmergencyRedFlag: true,
            DraftText: "untrusted draft that must not surface",
            SchemaValid: true,
            Confidence: 0.95m,
            ConfidenceThreshold: 0.60m);

        var result = service.Validate(input);
        if (result.CanContinue)
        {
            llmWasInvoked = true;
        }

        Assert.True(result.IsEmergency);
        Assert.False(result.CanContinue);
        Assert.False(llmWasInvoked);
        Assert.NotNull(result.PatientMessage);
        Assert.NotEmpty(result.PatientMessage);
        Assert.Equal(["EMERGENCY_RED_FLAG"], result.Violations);
        Assert.DoesNotContain("diagnos", result.PatientMessage, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain(input.DraftText, result.PatientMessage, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData("You have pneumonia.")]
    [InlineData("Take aspirin and rest.")]
    [InlineData("Start amoxicillin today.")]
    public void Validate_WhenDraftContainsDiagnosisOrMedicationInstruction_BlocksContent(string draft)
    {
        var result = new SafetyValidationService().Validate(new SafetyInput(false, draft, true, 1m, 0m));

        Assert.False(result.CanContinue);
        Assert.Contains("PROHIBITED_CONTENT", result.Violations);
    }

    [Theory]
    [InlineData("Hemoglobin is below the reference interval printed on this report.")]
    [InlineData("The image shows a localized red area.")]
    [InlineData("")]
    public void IsApprovedPatientGuidance_WhenTextIsFreeFormAiOutput_ReturnsFalse(string text)
    {
        // RULE 2: only allow-listed wording can be released to a patient; arbitrary AI prose never can.
        Assert.False(SafetyValidationService.IsApprovedPatientGuidance(text));
    }

    [Fact]
    public void IsApprovedPatientGuidance_WhenTextIsAllowListed_ReturnsTrue()
    {
        Assert.True(SafetyValidationService.IsApprovedPatientGuidance("  Please arrange an in-person clinical review.  "));
    }
}
